-- ============================================================
-- ElectriSys — Migración a Oracle 23ai
-- 02. DDL de tablas (equivalente a database/schema.sql +
--     schema_v2_migration.sql + schema_v3_migration_nlp.sql de MySQL)
-- Ejecutar conectado como el usuario ELECTRISYS.
--
-- Mapeo de tipos MySQL -> Oracle usado en esta migración:
--   INT UNSIGNED AUTO_INCREMENT  -> NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY
--   VARCHAR(n)                   -> VARCHAR2(n)
--   TEXT                         -> VARCHAR2(4000)  (ningún campo de texto libre
--                                    del proyecto supera ese tamaño en la práctica)
--   DECIMAL(p,s)                 -> NUMBER(p,s)
--   TINYINT(1) (booleano)        -> NUMBER(1)  (NO el BOOLEAN nativo de 23ai:
--                                    todo el backend PHP compara "= 1"/"= 0"
--                                    contra estas columnas — comparar eso
--                                    contra un BOOLEAN real da ORA-00932.
--                                    Se prioriza no reescribir cada comparación
--                                    del backend por este motivo.)
--   ENUM(...)                    -> VARCHAR2(n) + CHECK (columna IN (...))
--   TIMESTAMP DEFAULT CURRENT_TIMESTAMP        -> TIMESTAMP DEFAULT SYSTIMESTAMP
--   TIMESTAMP ... ON UPDATE CURRENT_TIMESTAMP  -> se replica con un trigger
--                                    (no existe equivalente declarativo en Oracle;
--                                    ver 04_triggers.sql)
--   JSON                         -> JSON  (tipo nativo desde Oracle 21c)
-- ============================================================

-- ── Roles de negocio (tabla de catálogo, no confundir con roles de Oracle) ──
CREATE TABLE roles (
    id        NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    nombre    VARCHAR2(50) NOT NULL,
    creado_en TIMESTAMP DEFAULT SYSTIMESTAMP,
    CONSTRAINT uq_roles_nombre UNIQUE (nombre)
);

INSERT INTO roles (nombre) VALUES ('admin');
INSERT INTO roles (nombre) VALUES ('vendedor');
INSERT INTO roles (nombre) VALUES ('dueno');

-- ── Usuarios ──────────────────────────────────────────────────────
CREATE TABLE usuarios (
    id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    nombre     VARCHAR2(100) NOT NULL,
    email      VARCHAR2(150) NOT NULL,
    password   VARCHAR2(255) NOT NULL,
    rol_id     NUMBER NOT NULL,
    activo     NUMBER(1) DEFAULT 1,
    creado_en  TIMESTAMP DEFAULT SYSTIMESTAMP,
    updated_at TIMESTAMP,
    deleted_at TIMESTAMP,
    CONSTRAINT uq_usuarios_email UNIQUE (email),
    CONSTRAINT fk_usuarios_rol FOREIGN KEY (rol_id) REFERENCES roles(id)
);

-- ── Proveedores ───────────────────────────────────────────────────
CREATE TABLE proveedores (
    id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    nombre     VARCHAR2(150) NOT NULL,
    contacto   VARCHAR2(100),
    telefono   VARCHAR2(30),
    email      VARCHAR2(150),
    direccion  VARCHAR2(4000),
    activo     NUMBER(1) DEFAULT 1,
    creado_en  TIMESTAMP DEFAULT SYSTIMESTAMP,
    updated_at TIMESTAMP,
    deleted_at TIMESTAMP
);

-- ── Categorías ────────────────────────────────────────────────────
CREATE TABLE categorias (
    id        NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    nombre    VARCHAR2(100) NOT NULL,
    creado_en TIMESTAMP DEFAULT SYSTIMESTAMP,
    CONSTRAINT uq_categorias_nombre UNIQUE (nombre)
);

-- ── Repuestos ─────────────────────────────────────────────────────
CREATE TABLE repuestos (
    id            NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    codigo        VARCHAR2(50),
    nombre        VARCHAR2(200) NOT NULL,
    descripcion   VARCHAR2(4000),
    categoria_id  NUMBER,
    proveedor_id  NUMBER,
    precio_compra NUMBER(12,2) DEFAULT 0 NOT NULL,
    precio_venta  NUMBER(12,2) DEFAULT 0 NOT NULL,
    stock         NUMBER(10) DEFAULT 0 NOT NULL,
    stock_minimo  NUMBER(10) DEFAULT 5 NOT NULL,
    activo        NUMBER(1) DEFAULT 1,
    creado_en     TIMESTAMP DEFAULT SYSTIMESTAMP,
    updated_at    TIMESTAMP,
    deleted_at    TIMESTAMP,
    CONSTRAINT uq_repuestos_codigo UNIQUE (codigo),
    CONSTRAINT fk_repuestos_categoria FOREIGN KEY (categoria_id) REFERENCES categorias(id),
    CONSTRAINT fk_repuestos_proveedor FOREIGN KEY (proveedor_id) REFERENCES proveedores(id),
    CONSTRAINT ck_repuestos_stock CHECK (stock >= 0),
    CONSTRAINT ck_repuestos_precios CHECK (precio_venta >= 0 AND precio_compra >= 0)
);

-- ── Clientes ──────────────────────────────────────────────────────
CREATE TABLE clientes (
    id             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    nombre         VARCHAR2(150) NOT NULL,
    identificacion VARCHAR2(30),
    tipo_doc       VARCHAR2(20) DEFAULT 'CC' NOT NULL,
    telefono       VARCHAR2(30),
    email          VARCHAR2(150),
    direccion      VARCHAR2(4000),
    activo         NUMBER(1) DEFAULT 1,
    creado_en      TIMESTAMP DEFAULT SYSTIMESTAMP,
    updated_at     TIMESTAMP,
    deleted_at     TIMESTAMP,
    CONSTRAINT uq_clientes_identificacion UNIQUE (identificacion),
    CONSTRAINT ck_clientes_tipo_doc CHECK (tipo_doc IN ('CC','NIT','CE','Pasaporte'))
);

-- ── Ventas ────────────────────────────────────────────────────────
CREATE TABLE ventas (
    id             NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    numero         VARCHAR2(20) NOT NULL,
    cliente_id     NUMBER,
    usuario_id     NUMBER NOT NULL,
    subtotal       NUMBER(14,2) DEFAULT 0 NOT NULL,
    descuento      NUMBER(14,2) DEFAULT 0 NOT NULL,
    impuesto       NUMBER(14,2) DEFAULT 0 NOT NULL,
    total          NUMBER(14,2) DEFAULT 0 NOT NULL,
    metodo_pago    VARCHAR2(20) DEFAULT 'efectivo' NOT NULL,
    estado         VARCHAR2(20) DEFAULT 'completada' NOT NULL,
    notas          VARCHAR2(4000),
    version        NUMBER DEFAULT 1,
    creado_en      TIMESTAMP DEFAULT SYSTIMESTAMP,
    updated_at     TIMESTAMP,
    CONSTRAINT uq_ventas_numero UNIQUE (numero),
    CONSTRAINT fk_ventas_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id),
    CONSTRAINT fk_ventas_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id),
    CONSTRAINT ck_ventas_metodo_pago CHECK (metodo_pago IN ('efectivo','tarjeta','transferencia','credito')),
    CONSTRAINT ck_ventas_estado CHECK (estado IN ('completada','anulada','pendiente')),
    CONSTRAINT ck_ventas_total CHECK (total >= 0)
);

-- ── Detalle de Ventas ─────────────────────────────────────────────
CREATE TABLE detalle_ventas (
    id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    venta_id    NUMBER NOT NULL,
    repuesto_id NUMBER NOT NULL,
    cantidad    NUMBER(10) DEFAULT 1 NOT NULL,
    precio_unit NUMBER(12,2) NOT NULL,
    descuento   NUMBER(12,2) DEFAULT 0 NOT NULL,
    subtotal    NUMBER(12,2) NOT NULL,
    CONSTRAINT fk_detven_venta    FOREIGN KEY (venta_id)    REFERENCES ventas(id) ON DELETE CASCADE,
    CONSTRAINT fk_detven_repuesto FOREIGN KEY (repuesto_id) REFERENCES repuestos(id),
    CONSTRAINT ck_detven_cantidad CHECK (cantidad > 0)
);

-- ── Cotizaciones ──────────────────────────────────────────────────
CREATE TABLE cotizaciones (
    id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    numero     VARCHAR2(20) NOT NULL,
    cliente_id NUMBER,
    usuario_id NUMBER NOT NULL,
    subtotal   NUMBER(14,2) DEFAULT 0 NOT NULL,
    descuento  NUMBER(14,2) DEFAULT 0 NOT NULL,
    impuesto   NUMBER(14,2) DEFAULT 0 NOT NULL,
    total      NUMBER(14,2) DEFAULT 0 NOT NULL,
    estado     VARCHAR2(20) DEFAULT 'borrador' NOT NULL,
    vence_en   DATE,
    notas      VARCHAR2(4000),
    creado_en  TIMESTAMP DEFAULT SYSTIMESTAMP,
    updated_at TIMESTAMP,
    CONSTRAINT uq_cotizaciones_numero UNIQUE (numero),
    CONSTRAINT fk_cotiz_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id),
    CONSTRAINT fk_cotiz_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id),
    CONSTRAINT ck_cotiz_estado CHECK (estado IN ('borrador','enviada','aceptada','rechazada','vencida'))
);

-- ── Detalle de Cotizaciones ───────────────────────────────────────
CREATE TABLE detalle_cotizaciones (
    id            NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    cotizacion_id NUMBER NOT NULL,
    repuesto_id   NUMBER NOT NULL,
    cantidad      NUMBER(10) DEFAULT 1 NOT NULL,
    precio_unit   NUMBER(12,2) NOT NULL,
    descuento     NUMBER(12,2) DEFAULT 0 NOT NULL,
    subtotal      NUMBER(12,2) NOT NULL,
    CONSTRAINT fk_detcot_cotizacion FOREIGN KEY (cotizacion_id) REFERENCES cotizaciones(id) ON DELETE CASCADE,
    CONSTRAINT fk_detcot_repuesto   FOREIGN KEY (repuesto_id)   REFERENCES repuestos(id)
);

-- ── Vehículos (compatibilidad del asistente NLP) ─────────────────
CREATE TABLE vehiculos (
    id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    marca       VARCHAR2(80) NOT NULL,
    modelo      VARCHAR2(80) NOT NULL,
    anio_desde  NUMBER(4) NOT NULL,
    anio_hasta  NUMBER(4) NOT NULL,
    motor       VARCHAR2(50),
    combustible VARCHAR2(20) DEFAULT 'gasolina' NOT NULL,
    creado_en   TIMESTAMP DEFAULT SYSTIMESTAMP,
    CONSTRAINT uq_vehiculo UNIQUE (marca, modelo, anio_desde, anio_hasta, motor, combustible),
    CONSTRAINT ck_vehiculos_combustible CHECK (combustible IN ('gasolina','diesel','hibrido','electrico','gas')),
    CONSTRAINT ck_vehiculos_anios CHECK (anio_hasta >= anio_desde)
);

-- ── Compatibilidad repuesto <-> vehículo (N:N) ────────────────────
CREATE TABLE repuesto_compatibilidad (
    id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    repuesto_id NUMBER NOT NULL,
    vehiculo_id NUMBER NOT NULL,
    creado_en   TIMESTAMP DEFAULT SYSTIMESTAMP,
    CONSTRAINT fk_compat_repuesto FOREIGN KEY (repuesto_id) REFERENCES repuestos(id) ON DELETE CASCADE,
    CONSTRAINT fk_compat_vehiculo FOREIGN KEY (vehiculo_id) REFERENCES vehiculos(id) ON DELETE CASCADE,
    CONSTRAINT uq_repuesto_vehiculo UNIQUE (repuesto_id, vehiculo_id)
);

-- ── Log de consultas al asistente NLP ─────────────────────────────
-- texto_consulta a VARCHAR2(4000) (no 1000): la regla de mapeo de este
-- mismo archivo dice TEXT->VARCHAR2(4000); acá se había quedado corto.
-- util: feedback de curación manual (ver database/schema_v4_migration_feedback.sql
-- del lado MySQL, agregado ahí primero) — NULL sin votar, 1 útil, 0 no útil.
CREATE TABLE consultas_asistente (
    id                  NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    usuario_id          NUMBER,
    texto_consulta      VARCHAR2(4000) NOT NULL,
    intencion_detectada VARCHAR2(50),
    entidades_json      JSON,
    respuesta_json      JSON,
    util                NUMBER(1) DEFAULT NULL,
    creado_en           TIMESTAMP DEFAULT SYSTIMESTAMP,
    CONSTRAINT fk_consultas_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id)
);

-- ── Audit Log ─────────────────────────────────────────────────────
CREATE TABLE audit_log (
    id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    usuario_id NUMBER,
    accion     VARCHAR2(100) NOT NULL,
    detalle    VARCHAR2(4000),
    ip         VARCHAR2(45),
    created_at TIMESTAMP DEFAULT SYSTIMESTAMP
);

-- ── Login Attempts (rate limiting) ────────────────────────────────
CREATE TABLE login_attempts (
    id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    ip         VARCHAR2(45) NOT NULL,
    created_at TIMESTAMP DEFAULT SYSTIMESTAMP
);

